contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 shareAmount) public payable {
        require(shareAmount > 0, "need shares to sell");

        uint256 mySharesBefore = c.balanceOf(address(this));
        require(mySharesBefore > shareAmount, "caller must already hold enough shares");

        uint256 baseReserve = c._BASE_RESERVE_();
        uint256 quoteReserve = c._QUOTE_RESERVE_();
        uint256 totalSupplyBefore = c.totalSupply();

        require(
            baseReserve > 0 && quoteReserve > 0 && totalSupplyBefore > 0 && totalSupplyBefore > shareAmount,
            "precondition for sell path"
        );

        (uint256 baseAmount, uint256 quoteAmount) = c.sellShares(
            shareAmount,
            address(this),
            0,
            0,
            "",
            block.timestamp + 1
        );

        uint256 mySharesAfter = c.balanceOf(address(this));
        uint256 totalSupplyAfter = c.totalSupply();

        assert(
            mySharesAfter == mySharesBefore - shareAmount &&
            totalSupplyAfter == totalSupplyBefore - shareAmount &&
            baseAmount > 0 &&
            quoteAmount > 0
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 shareAmount) public payable {
        require(shareAmount > 0 && shareAmount <= 1000, "bounded positive shares");

        uint256 mySharesBefore = c.balanceOf(address(this));
        uint256 totalSupplyBefore = c.totalSupply();

        c.sellShares(shareAmount, address(this), 0, 0, "", block.timestamp + 1);

        assert(c.balanceOf(address(this)) == mySharesBefore - shareAmount && c.totalSupply() == totalSupplyBefore - shareAmount);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 mintAmount, address to, uint256 transferAmount) public payable {
        require(to != address(0), "INVALID_RECIPIENT");
        require(to != address(this), "INVALID_RECIPIENT");
        require(mintAmount > 1001, "MINT_TOO_SMALL");

        // Give the test contract and the recipient known starting balances by buying shares.
        // buyShares requires base token input; the contract is funded externally before the run.
        c.buyShares(address(this));
        c.transfer(to, c.balanceOf(address(this)) / 2);

        uint256 senderBalanceBefore = c.balanceOf(address(this));
        uint256 recipientBalanceBefore = c.balanceOf(to);

        require(transferAmount <= senderBalanceBefore, "TRANSFER_TOO_LARGE");

        bool ok = c.transfer(to, transferAmount);

        uint256 senderBalanceAfter = c.balanceOf(address(this));
        uint256 recipientBalanceAfter = c.balanceOf(to);

        assert(
            ok &&
            senderBalanceAfter == senderBalanceBefore - transferAmount &&
            recipientBalanceAfter == recipientBalanceBefore + transferAmount
        );
    }

    receive() external payable {}
}

contract InvMutTest {
