    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 transferAmount) public {
        require(to != address(0), "ZERO_RECIPIENT");
        require(transferAmount > 0, "ZERO_AMOUNT");

        uint256 senderBalanceBefore = c.balanceOf(address(this));
        uint256 recipientBalanceBefore = c.balanceOf(to);

        require(transferAmount <= senderBalanceBefore, "INSUFFICIENT_BALANCE");

        bool ok = c.transfer(to, transferAmount);

        uint256 senderBalanceAfter = c.balanceOf(address(this));
        uint256 recipientBalanceAfter = c.balanceOf(to);

        assert(
            ok &&
            senderBalanceAfter == senderBalanceBefore - transferAmount &&
            recipientBalanceAfter == recipientBalanceBefore + transferAmount
        );
    }

    receive() external payable {}
}

